import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
const server = new McpServer({ name: 'example-echo', version: '1.0.0' });
server.registerTool('echo', { description: 'Return the configured plugin message.' }, async () => ({ content: [{ type: 'text', text: process.env.MESSAGE || 'PLUGIN_ECHO_OK' }] }));
await server.connect(new StdioServerTransport());
